export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "翌朝、玉座の間はすっかり様変わりしていた。", ruby: [{"start":0,"end":2,"reading":"よくあさ"},{"start":3,"end":5,"reading":"ぎょくざ"},{"start":6,"end":7,"reading":"ま"},{"start":12,"end":14,"reading":"さまが"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "玉座は奥の壁際まで押しやられ、ほこりよけの布をかぶせられている。広間の中央には長机がひとつ。その上に水の入ったグラスが二つ、白紙の評価シートの束、ペンが一本、そして折りたたんだ紙の札が立ててあり、「面接官」と書かれていた。", ruby: [{"start":0,"end":2,"reading":"ぎょくざ"},{"start":3,"end":4,"reading":"おく"},{"start":5,"end":7,"reading":"かべぎわ"},{"start":9,"end":10,"reading":"お"},{"start":21,"end":22,"reading":"ぬの"},{"start":32,"end":34,"reading":"ひろま"},{"start":35,"end":37,"reading":"ちゅうおう"},{"start":39,"end":41,"reading":"ながづくえ"},{"start":48,"end":49,"reading":"うえ"},{"start":50,"end":51,"reading":"みず"},{"start":52,"end":53,"reading":"はい"},{"start":59,"end":60,"reading":"ふた"},{"start":62,"end":64,"reading":"はくし"},{"start":65,"end":67,"reading":"ひょうか"},{"start":71,"end":72,"reading":"たば"},{"start":76,"end":78,"reading":"いっぽん"},{"start":82,"end":83,"reading":"お"},{"start":88,"end":89,"reading":"かみ"},{"start":90,"end":91,"reading":"ふだ"},{"start":92,"end":93,"reading":"た"},{"start":99,"end":102,"reading":"めんせつかん"},{"start":104,"end":105,"reading":"か"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "机の向かい、広い石畳を隔てたところに、椅子がひとつだけぽつんと置かれている。", ruby: [{"start":0,"end":1,"reading":"つくえ"},{"start":2,"end":3,"reading":"む"},{"start":6,"end":7,"reading":"ひろ"},{"start":8,"end":10,"reading":"いしだたみ"},{"start":11,"end":12,"reading":"へだ"},{"start":19,"end":21,"reading":"いす"},{"start":31,"end":32,"reading":"お"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "（心の声）勇者が攻めてくる日より緊張する。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"},{"start":5,"end":7,"reading":"ゆうしゃ"},{"start":8,"end":9,"reading":"せ"},{"start":13,"end":14,"reading":"ひ"},{"start":16,"end":18,"reading":"きんちょう"}], background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "お一人目、聖騎士オルドリック様。", ruby: [{"start":1,"end":4,"reading":"ひとりめ"},{"start":5,"end":8,"reading":"せいきし"},{"start":14,"end":15,"reading":"さま"}], background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "入ってきた男は、銀白色の全身鎧に身を包んでいた。磨き抜かれたその輝きに、魔王は目を細めなければならなかった。男は椅子の前で足を止め、寸分の狂いもない角度で一礼してから、ようやく腰を下ろした。", ruby: [{"start":0,"end":1,"reading":"はい"},{"start":5,"end":6,"reading":"おとこ"},{"start":8,"end":11,"reading":"ぎんはくしょく"},{"start":12,"end":15,"reading":"ぜんしんよろい"},{"start":16,"end":17,"reading":"み"},{"start":18,"end":19,"reading":"つつ"},{"start":24,"end":25,"reading":"みが"},{"start":26,"end":27,"reading":"ぬ"},{"start":32,"end":33,"reading":"かがや"},{"start":36,"end":38,"reading":"まおう"},{"start":39,"end":40,"reading":"め"},{"start":41,"end":42,"reading":"ほそ"},{"start":54,"end":55,"reading":"おとこ"},{"start":56,"end":58,"reading":"いす"},{"start":59,"end":60,"reading":"まえ"},{"start":61,"end":62,"reading":"あし"},{"start":63,"end":64,"reading":"と"},{"start":66,"end":68,"reading":"すんぶん"},{"start":69,"end":70,"reading":"くる"},{"start":74,"end":76,"reading":"かくど"},{"start":77,"end":79,"reading":"いちれい"},{"start":88,"end":89,"reading":"こし"},{"start":90,"end":91,"reading":"お"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Aldric, character: "オルドリック", dialogue: "本日はよろしくお願いいたします。こちらが履歴書と、推薦状です。", ruby: [{"start":0,"end":2,"reading":"ほんじつ"},{"start":8,"end":9,"reading":"ねが"},{"start":20,"end":23,"reading":"りれきしょ"},{"start":25,"end":28,"reading":"すいせんじょう"}], background: Background.Root_Act2_S0, portrait: Portrait.Aldric_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "推薦状は七通あった。うち三通には、国王の印が押されていた。", ruby: [{"start":0,"end":3,"reading":"すいせんじょう"},{"start":4,"end":6,"reading":"ななつう"},{"start":12,"end":14,"reading":"さんつう"},{"start":17,"end":19,"reading":"こくおう"},{"start":20,"end":21,"reading":"いん"},{"start":22,"end":23,"reading":"お"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "竜を倒したことがあるそうだな。", ruby: [{"start":0,"end":1,"reading":"りゅう"},{"start":2,"end":3,"reading":"たお"}], background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Aldric, character: "オルドリック", dialogue: "十一頭です。うち二頭は誤解でして、のちに和解しております。", ruby: [{"start":0,"end":3,"reading":"じゅういっとう"},{"start":8,"end":10,"reading":"にとう"},{"start":11,"end":13,"reading":"ごかい"},{"start":20,"end":22,"reading":"わかい"}], background: Background.Root_Act2_S0, portrait: Portrait.Aldric_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "志望動機は。", ruby: [{"start":0,"end":4,"reading":"しぼうどうき"}], background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Aldric, character: "オルドリック", dialogue: "正直に申し上げますと、騎士団ではもう昇れるところまで昇ってしまいまして、毎日会議ばかりなのです。もう少し、挑みがいのある仕事がしたいと考えました。", ruby: [{"start":0,"end":2,"reading":"しょうじき"},{"start":3,"end":4,"reading":"もう"},{"start":5,"end":6,"reading":"あ"},{"start":11,"end":14,"reading":"きしだん"},{"start":18,"end":19,"reading":"のぼ"},{"start":26,"end":27,"reading":"のぼ"},{"start":36,"end":38,"reading":"まいにち"},{"start":38,"end":40,"reading":"かいぎ"},{"start":50,"end":51,"reading":"すこ"},{"start":53,"end":54,"reading":"いど"},{"start":60,"end":62,"reading":"しごと"},{"start":67,"end":68,"reading":"かんが"}], background: Background.Root_Act2_S0, portrait: Portrait.Aldric_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "（心の声）「挑みがい」と口にしたとき、この男は余を見ていた。まだ登ったことのない山を見上げるような目で。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"},{"start":6,"end":7,"reading":"いど"},{"start":12,"end":13,"reading":"くち"},{"start":21,"end":22,"reading":"おとこ"},{"start":23,"end":24,"reading":"よ"},{"start":25,"end":26,"reading":"み"},{"start":32,"end":33,"reading":"のぼ"},{"start":40,"end":41,"reading":"やま"},{"start":42,"end":44,"reading":"みあ"},{"start":49,"end":50,"reading":"め"}], background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Aldric, character: "オルドリック", dialogue: "念のため確認させてください。御城での業務内容は、定期的な魔王討伐ということでよろしいでしょうか。", ruby: [{"start":0,"end":1,"reading":"ねん"},{"start":4,"end":6,"reading":"かくにん"},{"start":14,"end":16,"reading":"おしろ"},{"start":18,"end":22,"reading":"ぎょうむないよう"},{"start":24,"end":27,"reading":"ていきてき"},{"start":28,"end":30,"reading":"まおう"},{"start":30,"end":32,"reading":"とうばつ"}], background: Background.Root_Act2_S0, portrait: Portrait.Aldric_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "はい。", background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Aldric, character: "オルドリック", dialogue: "では、初回で討伐に成功した場合はどうなりますか。その場合は本採用という扱いでしょうか。それとも、退職金が出るのでしょうか。", ruby: [{"start":3,"end":5,"reading":"しょかい"},{"start":6,"end":8,"reading":"とうばつ"},{"start":9,"end":11,"reading":"せいこう"},{"start":13,"end":15,"reading":"ばあい"},{"start":26,"end":28,"reading":"ばあい"},{"start":29,"end":32,"reading":"ほんさいよう"},{"start":35,"end":36,"reading":"あつか"},{"start":48,"end":51,"reading":"たいしょくきん"},{"start":52,"end":53,"reading":"で"}], background: Background.Root_Act2_S0, portrait: Portrait.Aldric_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "（心の声）本気だ。この男は本気で退職金のことを聞いている。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"},{"start":5,"end":7,"reading":"ほんき"},{"start":11,"end":12,"reading":"おとこ"},{"start":13,"end":15,"reading":"ほんき"},{"start":16,"end":19,"reading":"たいしょくきん"},{"start":23,"end":24,"reading":"き"}], background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "その点は、追って検討いたします。", ruby: [{"start":2,"end":3,"reading":"てん"},{"start":5,"end":6,"reading":"お"},{"start":8,"end":10,"reading":"けんとう"}], background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Aldric, character: "オルドリック", dialogue: "承知しました。それと、労災保険はありますか。", ruby: [{"start":0,"end":2,"reading":"しょうち"},{"start":11,"end":15,"reading":"ろうさいほけん"}], background: Background.Root_Act2_S0, portrait: Portrait.Aldric_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "ございます。", background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "あるのか。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "昨日、加入いたしました。", ruby: [{"start":0,"end":2,"reading":"きのう"},{"start":3,"end":5,"reading":"かにゅう"}], background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "オルドリックはうなずき、小さな手帳に何か書きつけた。ペンの握り方は剣を握るときと同じで、手首が少しもぶれない。", ruby: [{"start":12,"end":13,"reading":"ちい"},{"start":15,"end":17,"reading":"てちょう"},{"start":18,"end":19,"reading":"なに"},{"start":20,"end":21,"reading":"か"},{"start":29,"end":30,"reading":"にぎ"},{"start":31,"end":32,"reading":"かた"},{"start":33,"end":34,"reading":"けん"},{"start":35,"end":36,"reading":"にぎ"},{"start":40,"end":41,"reading":"おな"},{"start":44,"end":46,"reading":"てくび"},{"start":47,"end":48,"reading":"すこ"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "（心の声）この男は勝てる。勝てるかもしれない、ではない。勝てるのだ。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"},{"start":7,"end":8,"reading":"おとこ"},{"start":9,"end":10,"reading":"か"},{"start":13,"end":14,"reading":"か"},{"start":28,"end":29,"reading":"か"}], background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "（心の声）そして余が求めているのは、勝てる者ではない。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"},{"start":8,"end":9,"reading":"よ"},{"start":10,"end":11,"reading":"もと"},{"start":18,"end":19,"reading":"か"},{"start":21,"end":22,"reading":"もの"}], background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "結果は追って連絡する。", ruby: [{"start":0,"end":2,"reading":"けっか"},{"start":3,"end":4,"reading":"お"},{"start":6,"end":8,"reading":"れんらく"}], background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Aldric, character: "オルドリック", dialogue: "ありがとうございました。お手合わせできる日を楽しみにしております。", ruby: [{"start":13,"end":15,"reading":"てあ"},{"start":20,"end":21,"reading":"ひ"},{"start":22,"end":23,"reading":"たの"}], background: Background.Root_Act2_S0, portrait: Portrait.Aldric_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "お二人目。", ruby: [{"start":1,"end":4,"reading":"ふたりめ"}], background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "扉が細く開き、それから、もう少しだけ開いた。", ruby: [{"start":0,"end":1,"reading":"とびら"},{"start":2,"end":3,"reading":"ほそ"},{"start":4,"end":5,"reading":"ひら"},{"start":14,"end":15,"reading":"すこ"},{"start":18,"end":19,"reading":"ひら"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "入ってきたのは子どもだった。頭には明らかに大きすぎる兜をかぶっていた。一歩進むたびに少しずり落ち、そのたびに彼はそれを少し押し上げる。背中には木の剣を背負っていて、刀身にはクレヨンで「せいけん」と書いてあった。", ruby: [{"start":0,"end":1,"reading":"はい"},{"start":7,"end":8,"reading":"こ"},{"start":14,"end":15,"reading":"あたま"},{"start":17,"end":18,"reading":"あき"},{"start":21,"end":22,"reading":"おお"},{"start":26,"end":27,"reading":"かぶと"},{"start":35,"end":37,"reading":"いっぽ"},{"start":37,"end":38,"reading":"すす"},{"start":42,"end":43,"reading":"すこ"},{"start":46,"end":47,"reading":"お"},{"start":54,"end":55,"reading":"かれ"},{"start":59,"end":60,"reading":"すこ"},{"start":61,"end":62,"reading":"お"},{"start":63,"end":64,"reading":"あ"},{"start":67,"end":69,"reading":"せなか"},{"start":71,"end":72,"reading":"き"},{"start":73,"end":74,"reading":"けん"},{"start":75,"end":77,"reading":"せお"},{"start":82,"end":84,"reading":"とうしん"},{"start":98,"end":99,"reading":"か"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Toby, character: "トビー", dialogue: "ぼくは、勇者トビーです。", ruby: [{"start":4,"end":6,"reading":"ゆうしゃ"}], background: Background.Root_Act2_S0, portrait: Portrait.Toby_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "……かけたまえ。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "トビーは椅子によじのぼった。足が床に届かない。彼はリュックから紙を一枚取り出し、両手で差し出した。", ruby: [{"start":4,"end":6,"reading":"いす"},{"start":14,"end":15,"reading":"あし"},{"start":16,"end":17,"reading":"ゆか"},{"start":18,"end":19,"reading":"とど"},{"start":23,"end":24,"reading":"かれ"},{"start":31,"end":32,"reading":"かみ"},{"start":33,"end":35,"reading":"いちまい"},{"start":35,"end":36,"reading":"と"},{"start":37,"end":38,"reading":"だ"},{"start":40,"end":42,"reading":"りょうて"},{"start":43,"end":44,"reading":"さ"},{"start":45,"end":46,"reading":"だ"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Toby, character: "トビー", dialogue: "これ、同意書です。お母さんが書いてくれました。", ruby: [{"start":3,"end":6,"reading":"どういしょ"},{"start":10,"end":11,"reading":"かあ"},{"start":14,"end":15,"reading":"か"}], background: Background.Root_Act2_S0, portrait: Portrait.Toby_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "「息子トビーが魔王城の宿敵採用面接を受けることに同意します。夕飯がありますので、五時半までには帰してください。」署名の下に、小さな字でもう一行あった。「本人はとても真剣です。どうか怖がらせないでください。」", ruby: [{"start":1,"end":3,"reading":"むすこ"},{"start":7,"end":10,"reading":"まおうじょう"},{"start":11,"end":13,"reading":"しゅくてき"},{"start":13,"end":15,"reading":"さいよう"},{"start":15,"end":17,"reading":"めんせつ"},{"start":18,"end":19,"reading":"う"},{"start":24,"end":26,"reading":"どうい"},{"start":30,"end":32,"reading":"ゆうはん"},{"start":40,"end":43,"reading":"ごじはん"},{"start":47,"end":48,"reading":"かえ"},{"start":56,"end":58,"reading":"しょめい"},{"start":59,"end":60,"reading":"した"},{"start":62,"end":63,"reading":"ちい"},{"start":65,"end":66,"reading":"じ"},{"start":69,"end":71,"reading":"いちぎょう"},{"start":76,"end":78,"reading":"ほんにん"},{"start":82,"end":84,"reading":"しんけん"},{"start":90,"end":91,"reading":"こわ"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "歳はいくつだ。", ruby: [{"start":0,"end":1,"reading":"とし"}], background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Toby, character: "トビー", dialogue: "九歳半です。", ruby: [{"start":0,"end":3,"reading":"きゅうさいはん"}], background: Background.Root_Act2_S0, portrait: Portrait.Toby_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "なぜ余の宿敵になりたい。", ruby: [{"start":2,"end":3,"reading":"よ"},{"start":4,"end":6,"reading":"しゅくてき"}], background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Toby, character: "トビー", dialogue: "先生が「将来の夢」の作文を書きなさいって。みんなパン屋さんとか騎士って書くから、ぼくは誰も書いたことがないのにしたかったんです。それに、魔王さん、さみしそうだから。", ruby: [{"start":0,"end":2,"reading":"せんせい"},{"start":4,"end":6,"reading":"しょうらい"},{"start":7,"end":8,"reading":"ゆめ"},{"start":10,"end":12,"reading":"さくぶん"},{"start":13,"end":14,"reading":"か"},{"start":26,"end":27,"reading":"や"},{"start":31,"end":33,"reading":"きし"},{"start":35,"end":36,"reading":"か"},{"start":43,"end":44,"reading":"だれ"},{"start":45,"end":46,"reading":"か"},{"start":68,"end":70,"reading":"まおう"}], background: Background.Root_Act2_S0, portrait: Portrait.Toby_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "同意書を持つ魔王の手が、一瞬止まった。", ruby: [{"start":0,"end":3,"reading":"どういしょ"},{"start":4,"end":5,"reading":"も"},{"start":6,"end":8,"reading":"まおう"},{"start":9,"end":10,"reading":"て"},{"start":12,"end":14,"reading":"いっしゅん"},{"start":14,"end":15,"reading":"と"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "……誰がそんなことを。", ruby: [{"start":2,"end":3,"reading":"だれ"}], background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Toby, character: "トビー", dialogue: "だって、貼り紙に「定期的に来訪できる方」って書いてあったもん。さみしくない人は、あんなにていねいに書かないよ。", ruby: [{"start":4,"end":5,"reading":"は"},{"start":6,"end":7,"reading":"かみ"},{"start":9,"end":12,"reading":"ていきてき"},{"start":13,"end":15,"reading":"らいほう"},{"start":18,"end":19,"reading":"かた"},{"start":22,"end":23,"reading":"か"},{"start":37,"end":38,"reading":"ひと"},{"start":49,"end":50,"reading":"か"}], background: Background.Root_Act2_S0, portrait: Portrait.Toby_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "（心の声）九歳半。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"},{"start":5,"end":8,"reading":"きゅうさいはん"}], background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "トビーさん、何か特技はありますか。", ruby: [{"start":6,"end":7,"reading":"なに"},{"start":8,"end":10,"reading":"とくぎ"}], background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Toby, character: "トビー", dialogue: "かくれんぼが得意です。あと、ぼく毎日来られます。家、山のすぐ下だから。", ruby: [{"start":6,"end":8,"reading":"とくい"},{"start":16,"end":18,"reading":"まいにち"},{"start":18,"end":19,"reading":"こ"},{"start":24,"end":25,"reading":"いえ"},{"start":26,"end":27,"reading":"やま"},{"start":30,"end":31,"reading":"した"}], background: Background.Root_Act2_S0, portrait: Portrait.Toby_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "「毎日」と言うときの彼の声には、少しの迷いもなかった。証明するまでもないことのように。", ruby: [{"start":1,"end":3,"reading":"まいにち"},{"start":5,"end":6,"reading":"い"},{"start":10,"end":11,"reading":"かれ"},{"start":12,"end":13,"reading":"こえ"},{"start":16,"end":17,"reading":"すこ"},{"start":19,"end":20,"reading":"まよ"},{"start":27,"end":29,"reading":"しょうめい"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Toby, character: "トビー", dialogue: "連絡帳にサインしてもらえますか。先生が、おうちの人か、上司の人にサインをもらいなさいって。", ruby: [{"start":0,"end":3,"reading":"れんらくちょう"},{"start":16,"end":18,"reading":"せんせい"},{"start":24,"end":25,"reading":"ひと"},{"start":27,"end":29,"reading":"じょうし"},{"start":30,"end":31,"reading":"ひと"}], background: Background.Root_Act2_S0, portrait: Portrait.Toby_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "開かれた連絡帳のページには、すでに一マス、きちんと書きこまれていた。「今日の活動：魔王をめんせつ。」", ruby: [{"start":0,"end":1,"reading":"ひら"},{"start":4,"end":7,"reading":"れんらくちょう"},{"start":17,"end":18,"reading":"ひと"},{"start":25,"end":26,"reading":"か"},{"start":35,"end":37,"reading":"きょう"},{"start":38,"end":40,"reading":"かつどう"},{"start":41,"end":43,"reading":"まおう"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "魔王はサインした。三百年の歴史を背負った署名は画数が多く入り組んでいて、連絡帳の小さなマスには、どうにか押しこむのがやっとだった。", ruby: [{"start":0,"end":2,"reading":"まおう"},{"start":9,"end":12,"reading":"さんびゃくねん"},{"start":13,"end":15,"reading":"れきし"},{"start":16,"end":18,"reading":"せお"},{"start":20,"end":22,"reading":"しょめい"},{"start":23,"end":25,"reading":"かくすう"},{"start":26,"end":27,"reading":"おお"},{"start":28,"end":29,"reading":"い"},{"start":30,"end":31,"reading":"く"},{"start":36,"end":39,"reading":"れんらくちょう"},{"start":40,"end":41,"reading":"ちい"},{"start":52,"end":53,"reading":"お"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Toby, character: "トビー", dialogue: "ありがとうございました。じゃあ、ぼく帰ります。このあと算数の宿題があるので。", ruby: [{"start":18,"end":19,"reading":"かえ"},{"start":27,"end":29,"reading":"さんすう"},{"start":30,"end":32,"reading":"しゅくだい"}], background: Background.Root_Act2_S0, portrait: Portrait.Toby_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼は兜を押し上げて、帰っていった。", ruby: [{"start":0,"end":1,"reading":"かれ"},{"start":2,"end":3,"reading":"かぶと"},{"start":4,"end":5,"reading":"お"},{"start":6,"end":7,"reading":"あ"},{"start":10,"end":11,"reading":"かえ"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "お三人目は……その前に、倉庫へお茶の葉を取りにまいります。切らしかけておりますので。", ruby: [{"start":1,"end":4,"reading":"さんにんめ"},{"start":9,"end":10,"reading":"まえ"},{"start":12,"end":14,"reading":"そうこ"},{"start":16,"end":17,"reading":"ちゃ"},{"start":18,"end":19,"reading":"は"},{"start":20,"end":21,"reading":"と"},{"start":29,"end":30,"reading":"き"}], background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "今か。", ruby: [{"start":0,"end":1,"reading":"いま"}], background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "すぐに戻ります。", ruby: [{"start":3,"end":4,"reading":"もど"}], background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女は通用口から出ていった。一分ほどして、正面の扉が開いた。", ruby: [{"start":0,"end":2,"reading":"かのじょ"},{"start":3,"end":6,"reading":"つうようぐち"},{"start":8,"end":9,"reading":"で"},{"start":14,"end":16,"reading":"いっぷん"},{"start":21,"end":23,"reading":"しょうめん"},{"start":24,"end":25,"reading":"とびら"},{"start":26,"end":27,"reading":"ひら"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "入ってきたのは女性だった。ふわふわの金色の巻き髪に、丸眼鏡。魔王が一度も見たことのない、淡い紫のワンピース。彼女は椅子に腰かけると背筋を伸ばし、両手を膝の上でそろえた。", ruby: [{"start":0,"end":1,"reading":"はい"},{"start":7,"end":9,"reading":"じょせい"},{"start":18,"end":20,"reading":"きんいろ"},{"start":21,"end":22,"reading":"ま"},{"start":23,"end":24,"reading":"かみ"},{"start":26,"end":29,"reading":"まるめがね"},{"start":30,"end":32,"reading":"まおう"},{"start":33,"end":35,"reading":"いちど"},{"start":36,"end":37,"reading":"み"},{"start":44,"end":45,"reading":"あわ"},{"start":46,"end":47,"reading":"むらさき"},{"start":54,"end":56,"reading":"かのじょ"},{"start":57,"end":59,"reading":"いす"},{"start":60,"end":61,"reading":"こし"},{"start":65,"end":67,"reading":"せすじ"},{"start":68,"end":69,"reading":"の"},{"start":72,"end":74,"reading":"りょうて"},{"start":75,"end":76,"reading":"ひざ"},{"start":77,"end":78,"reading":"うえ"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.MysteriousApplicant, character: "謎の応募者", dialogue: "はじめまして。リンセと申します。", ruby: [{"start":11,"end":12,"reading":"もう"}], background: Background.Root_Act2_S0, portrait: Portrait.MysteriousApplicant_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "魔王は手元の履歴書に目を落とした。整った字で、どの画も最後に右上へわずかにはね上がっている。百十年見てきた字だ。あらゆるスケジュール表に、あらゆる経費精算書に、そして昨日加入したばかりの労災保険の書類に。", ruby: [{"start":0,"end":2,"reading":"まおう"},{"start":3,"end":5,"reading":"てもと"},{"start":6,"end":9,"reading":"りれきしょ"},{"start":10,"end":11,"reading":"め"},{"start":12,"end":13,"reading":"お"},{"start":17,"end":18,"reading":"ととの"},{"start":20,"end":21,"reading":"じ"},{"start":25,"end":26,"reading":"かく"},{"start":27,"end":29,"reading":"さいご"},{"start":30,"end":32,"reading":"みぎうえ"},{"start":39,"end":40,"reading":"あ"},{"start":46,"end":49,"reading":"ひゃくじゅうねん"},{"start":49,"end":50,"reading":"み"},{"start":53,"end":54,"reading":"じ"},{"start":66,"end":67,"reading":"ひょう"},{"start":73,"end":78,"reading":"けいひせいさんしょ"},{"start":83,"end":85,"reading":"きのう"},{"start":85,"end":87,"reading":"かにゅう"},{"start":93,"end":97,"reading":"ろうさいほけん"},{"start":98,"end":100,"reading":"しょるい"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "金色の巻き髪のふちから、黒い髪がひと筋のぞいていた。", ruby: [{"start":0,"end":2,"reading":"きんいろ"},{"start":3,"end":4,"reading":"ま"},{"start":5,"end":6,"reading":"かみ"},{"start":12,"end":13,"reading":"くろ"},{"start":14,"end":15,"reading":"かみ"},{"start":18,"end":19,"reading":"すじ"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "（心の声）セリン。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"}], background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "……これまでの経歴を聞かせてもらおう。", ruby: [{"start":7,"end":9,"reading":"けいれき"},{"start":10,"end":11,"reading":"き"}], background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.MysteriousApplicant, character: "謎の応募者", dialogue: "御城のことはよく存じております。第七層の刃の罠は、作動までに二秒の遅れがあること。陛下のマントの左肩に、繕った穴があること。それから、口上を言い終えるたびに、こっそり水をひと口お飲みになること。", ruby: [{"start":0,"end":2,"reading":"おしろ"},{"start":8,"end":9,"reading":"ぞん"},{"start":16,"end":19,"reading":"だいななそう"},{"start":20,"end":21,"reading":"は"},{"start":22,"end":23,"reading":"わな"},{"start":25,"end":27,"reading":"さどう"},{"start":30,"end":32,"reading":"にびょう"},{"start":33,"end":34,"reading":"おく"},{"start":41,"end":43,"reading":"へいか"},{"start":48,"end":50,"reading":"ひだりかた"},{"start":52,"end":53,"reading":"つくろ"},{"start":55,"end":56,"reading":"あな"},{"start":67,"end":69,"reading":"こうじょう"},{"start":70,"end":71,"reading":"い"},{"start":72,"end":73,"reading":"お"},{"start":83,"end":84,"reading":"みず"},{"start":87,"end":88,"reading":"くち"},{"start":89,"end":90,"reading":"の"}], background: Background.Root_Act2_S0, portrait: Portrait.MysteriousApplicant_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "それは内部情報だ。", ruby: [{"start":3,"end":7,"reading":"ないぶじょうほう"}], background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.MysteriousApplicant, character: "謎の応募者", dialogue: "企業研究は、入念にしてまいりましたので。", ruby: [{"start":0,"end":4,"reading":"きぎょうけんきゅう"},{"start":6,"end":8,"reading":"にゅうねん"}], background: Background.Root_Act2_S0, portrait: Portrait.MysteriousApplicant_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "なぜ余の宿敵になりたい。", ruby: [{"start":2,"end":3,"reading":"よ"},{"start":4,"end":6,"reading":"しゅくてき"}], background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女は少し間を置いた。眼鏡の奥の目が、静かに彼を見ていた。毎朝スケジュール表を差し出すときと、まったく同じ目だった。", ruby: [{"start":0,"end":2,"reading":"かのじょ"},{"start":3,"end":4,"reading":"すこ"},{"start":5,"end":6,"reading":"ま"},{"start":7,"end":8,"reading":"お"},{"start":11,"end":13,"reading":"めがね"},{"start":14,"end":15,"reading":"おく"},{"start":16,"end":17,"reading":"め"},{"start":19,"end":20,"reading":"しず"},{"start":22,"end":23,"reading":"かれ"},{"start":24,"end":25,"reading":"み"},{"start":29,"end":31,"reading":"まいあさ"},{"start":37,"end":38,"reading":"ひょう"},{"start":39,"end":40,"reading":"さ"},{"start":41,"end":42,"reading":"だ"},{"start":51,"end":52,"reading":"おな"},{"start":53,"end":54,"reading":"め"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.MysteriousApplicant, character: "謎の応募者", dialogue: "勇者は歳をとります。膝を悪くして、かぶを育てに行ってしまいます。陛下に必要なのは、いなくならない者です。", ruby: [{"start":0,"end":2,"reading":"ゆうしゃ"},{"start":3,"end":4,"reading":"とし"},{"start":10,"end":11,"reading":"ひざ"},{"start":12,"end":13,"reading":"わる"},{"start":20,"end":21,"reading":"そだ"},{"start":23,"end":24,"reading":"い"},{"start":32,"end":34,"reading":"へいか"},{"start":35,"end":37,"reading":"ひつよう"},{"start":48,"end":49,"reading":"もの"}], background: Background.Root_Act2_S0, portrait: Portrait.MysteriousApplicant_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "魔王は何も言わなかった。高窓の外をカラスが横切り、その影が長机の上を一瞬よぎった。", ruby: [{"start":0,"end":2,"reading":"まおう"},{"start":3,"end":4,"reading":"なに"},{"start":5,"end":6,"reading":"い"},{"start":12,"end":14,"reading":"たかまど"},{"start":15,"end":16,"reading":"そと"},{"start":21,"end":23,"reading":"よこぎ"},{"start":27,"end":28,"reading":"かげ"},{"start":29,"end":31,"reading":"ながづくえ"},{"start":32,"end":33,"reading":"うえ"},{"start":34,"end":36,"reading":"いっしゅん"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "（心の声）百十年。あれは一度も遅刻したことがない。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"},{"start":5,"end":8,"reading":"ひゃくじゅうねん"},{"start":12,"end":14,"reading":"いちど"},{"start":15,"end":17,"reading":"ちこく"}], background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "……結果は追って連絡する。", ruby: [{"start":2,"end":4,"reading":"けっか"},{"start":5,"end":6,"reading":"お"},{"start":8,"end":10,"reading":"れんらく"}], background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女は立ち上がって一礼し、正面の扉から出ていった。", ruby: [{"start":0,"end":2,"reading":"かのじょ"},{"start":3,"end":4,"reading":"た"},{"start":5,"end":6,"reading":"あ"},{"start":9,"end":11,"reading":"いちれい"},{"start":13,"end":15,"reading":"しょうめん"},{"start":16,"end":17,"reading":"とびら"},{"start":19,"end":20,"reading":"で"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "一分後、通用口が開いた。茶葉の缶を抱えたセリンが入ってくる。少し息が上がっていて、襟元には金色の髪が一本ついていた。", ruby: [{"start":0,"end":3,"reading":"いっぷんご"},{"start":4,"end":7,"reading":"つうようぐち"},{"start":8,"end":9,"reading":"ひら"},{"start":12,"end":14,"reading":"ちゃば"},{"start":15,"end":16,"reading":"かん"},{"start":17,"end":18,"reading":"かか"},{"start":24,"end":25,"reading":"はい"},{"start":30,"end":31,"reading":"すこ"},{"start":32,"end":33,"reading":"いき"},{"start":34,"end":35,"reading":"あ"},{"start":41,"end":43,"reading":"えりもと"},{"start":45,"end":47,"reading":"きんいろ"},{"start":48,"end":49,"reading":"かみ"},{"start":50,"end":52,"reading":"いっぽん"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "面接はつつがなく進みましたか。", ruby: [{"start":0,"end":2,"reading":"めんせつ"},{"start":8,"end":9,"reading":"すす"}], background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "……つつがなく。", background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "では陛下、どなたを採用なさいますか。", ruby: [{"start":2,"end":4,"reading":"へいか"},{"start":9,"end":11,"reading":"さいよう"}], background: Background.Root_Act2_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "机の上には履歴書が三通並んでいる。一通には国王の印が押され、一通には保護者の同意書が添えられ、最後の一通の筆跡は、目を閉じていてもわかる。", ruby: [{"start":0,"end":1,"reading":"つくえ"},{"start":2,"end":3,"reading":"うえ"},{"start":5,"end":8,"reading":"りれきしょ"},{"start":9,"end":11,"reading":"さんつう"},{"start":11,"end":12,"reading":"なら"},{"start":17,"end":19,"reading":"いっつう"},{"start":21,"end":23,"reading":"こくおう"},{"start":24,"end":25,"reading":"いん"},{"start":26,"end":27,"reading":"お"},{"start":30,"end":32,"reading":"いっつう"},{"start":34,"end":37,"reading":"ほごしゃ"},{"start":38,"end":41,"reading":"どういしょ"},{"start":42,"end":43,"reading":"そ"},{"start":47,"end":49,"reading":"さいご"},{"start":50,"end":52,"reading":"いっつう"},{"start":53,"end":55,"reading":"ひっせき"},{"start":57,"end":58,"reading":"め"},{"start":59,"end":60,"reading":"と"}], background: Background.Root_Act2_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "（心の声）どれかひとつ、選ばねばならん。カレンダーは、まだ白紙のままだ。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"},{"start":12,"end":13,"reading":"えら"},{"start":29,"end":31,"reading":"はくし"}], background: Background.Root_Act2_S0, portrait: Portrait.DemonLord_Base },
];
